INSERT INTO `san_shop_sider` (`id`, `identifier`, `titel`, `indhold`, `count`, `search_title`, `search_meta_desc`, `search_meta_tags`, `contact_text`, `belongs_to`, `language_id`) VALUES
(1, 'forside', 'Forside', '<p><em>Cloud Router&nbsp;etablerer et v&aelig;rdiskabende samarbejde der skaber b&aelig;redygtige relationer.</em></p>', 0, 'Cloud Router - Radiokæde og WiFi løsninger', 'Radiokæde og WiFi løsninger til professionelt brug', 'Distributør, leverandør, WiFi, WLAN, punkt til punkt, Ethernet, WAN, M2M, IoT, Radiolink, radio link, trådløs bro, WLAN bridge, WiFi bro, WiFi bridge, trådløst netværk, skole netværk, industri netværk, routing, switching, switch, router, firewall', '', '', 1),
(7, NULL, 'Informationer', 'Indtast din tekst her.', 0, '', '', '', '', '', 1),
(6, NULL, 'service_bund', '', 0, '', '', '', '', '', 1),
(2, 'betingelser', 'Terms DK', '<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><strong>Almindelige salgs- og leveringsbetingelser (handelsbetingelser) -&nbsp;G&aelig;ldende for erhvervsk&oslash;b</strong></span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">1. Definitioner</span><br /><span style=\"color: #333333;\">I handelsbetingelser mellem parterne defineres: Arbejdsdage som mandag til fredag undtagen helligdage, 1. maj, juleaftensdag og nyt&aring;rsaftensdag. Normal arbejdstid er arbejdsdage i tidsrummet 8:30 til 16:00. I handelsbetingelser mellem parterne defineres k&oslash;ber som kunden og s&aelig;lger som Cloud Router ApS, CVR-nummer 36722339 (herefter ben&aelig;vnt Cloud Router).</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">2. Anvendelse og omfang </span><br /><span style=\"color: #333333;\">N&aelig;rv&aelig;rende almindelige salgs- og leveringsbetingelser (herefter ben&aelig;vnt handelsbetingelser) g&aelig;lder for alle aftaler om Cloud Routers salg og levering af varer samt tilknyttede tjenesteydelser til erhvervskunder og det offentlige. I det omfang andet ikke er skriftligt aftalt, er nedenfor angivne handelsbetingelser g&aelig;ldende og g&aring;r forud for kundens eventuelle almindelige betingelser.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">3. Aftalegrundlag</span><br /><span style=\"color: #333333;\">Handelsbetingelser udg&oslash;r sammen med Cloud Routers tilbud og ordrebekr&aelig;ftelser det samlede aftalegrundlag om Cloud Routers salg og levering af varer og tilknyttede ydelser til kunden (&rdquo;Aftalegrundlaget&rdquo;). Kundens indk&oslash;bsbetingelser trykt p&aring; ordrer eller p&aring; anden m&aring;de meddelt til Cloud Router udg&oslash;r ikke en del af Aftalegrundlaget.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">4. Persondatapolitik</span><br /><span style=\"color: #333333;\">Cloud Router behandler persondata i henhold til den g&aelig;ldende persondataforordning, der tr&aring;dte i kraft d. 25. maj 2018. Som registreret kunde hos Cloud Router har kunden altid mulighed for indsigt, og kan g&oslash;re indsigelse mod en registrering i henhold til reglerne i persondataforordningen. Henvendelser i forbindelse med persondataloven kan du rette til kontor@cloudrouter.dk. </span><br /><span style=\"color: #333333;\">Kundens personlige data/oplysninger vil udelukkende blive brugt i Cloud Routers interne kunde- og &oslash;konomisystem, med det form&aring;l at kunne tilbyde kundens medarbejdere et personligt login til Cloud Routers forhandlerportal samt at kunne levere varen til kunden. Det skal dog oplyses at vi anvender cookies p&aring; cloudrouter.dk. Det er udelukkende med det form&aring;l at optimere vores webshop og dens funktionalitet for kunden. Der er ikke gemt nogen form for personlige oplysninger i vores cookies. Kunden har altid mulighed for at slette dem fra kundens computer. Vi registrerer kontaktpersonens fulde navn, e-mailadresse, firmanavn, cvr-nummer og firma adresse. Der registreres ikke andre personf&oslash;lsomme oplysninger. Oplysningerne videregives ikke til tredjemand.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">5. Tilbud og bestilling</span><br /><span style=\"color: #333333;\">Alle tilbud fra Cloud Router er bindende i 30 dage fra tilbudsdato, med mindre andet er udtrykkeligt aftalt mellem parterne specifikt pr. tilbud. Kunden skal sende ordrer p&aring; varer eller tilknyttede ydelser til Cloud Router skriftligt p&aring; salg@cloudrouter.dk eller via Cloud Routers webbutik p&aring; www.cloudrouter.dk.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">6. Ydelser</span><br /><span style=\"color: #333333;\">Alle ydelser fysiske, s&aring;vel som fjernydelser faktureres pr. p&aring;begyndt time. Ved fysiske ydelser p&aring;l&aelig;gges transportudgifter, hotelophold m.v. Kunden faktureres efter g&aelig;ldende takster, medmindre andet er skriftligt aftalt, og er specifikt beskrevet pr. sag.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">7. Ordrebekr&aelig;ftelse</span><br /><span style=\"color: #333333;\">Afgivne ordrer er f&oslash;rst forpligtende for Cloud Router, n&aring;r kunden har modtaget Cloud Routers skriftlige ordrebekr&aelig;ftelse. Cloud Router fraskriver sig ethvert ansvar for eventuelle fejl og oplysninger i materiale udformet af tredjemand. Dette g&aelig;lder enhver form for salgsmateriale, beskrivelser, brugervejledning, indhold p&aring; andre websites m.v.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">8. Priser</span><br /><span style=\"color: #333333;\">Prisen for varer og tilknyttede ydelser f&oslash;lger Cloud Routers g&aelig;ldende prisliste p&aring; det tidspunkt, hvor Cloud Router bekr&aelig;fter kundens ordre, medmindre parterne har aftalt andet skriftligt. Alle priser er eksklusive moms, transport, ekspeditionsgebyr, evt. gebyr og till&aelig;g.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">9. Ejendomsret</span><br /><span style=\"color: #333333;\">Cloud Router forbeholder sig ejendomsretten til de leverede varer, indtil den fulde betaling har fundet sted med till&aelig;g af p&aring;l&oslash;bne renter og omkostninger.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">10. Betaling</span><br /><span style=\"color: #333333;\">Med mindre andet er fastsat ved udtrykkelig skriftlig aftale eller fremg&aring;r af fakturaen, skal ordren betales med Dankort, Visa/Dankort, eDankort eller forudbetaling ved bestilling. Ved fakturabetaling, skal det fulde fakturabel&oslash;b i alle tilf&aelig;lde betales p&aring; forfaldsdato, angivet p&aring; fakturaen. Betales fakturabel&oslash;bet ikke rettidigt beregnes morarenter for forfaldsdagen p&aring; 2% pr. m&aring;ned af den til enhver tid v&aelig;rende restg&aelig;ld, samt et kompensationskrav p&aring; kr. 310 og rykkegebyr p&aring; kr. 100 pr. rykker. Forsinket betaling af en faktura anses altid som v&aelig;sentlig misligholdelse af aftalen.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">11. Forbehold</span><br /><span style=\"color: #333333;\">Cloud Router tager forbehold for valutakurser, eventuelle told, skatter, afgifter, pris- og korrekturfejl, tekniske fejl, udsolgte varer, force majeure, arbejdskonflikt og forsinkelse af leverancer fra underleverand&oslash;rer og producenter.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">12. Levering og leveringstid</span><br /><span style=\"color: #333333;\">Levering sker til adresser i Danmark igennem Post Danmark, GLS eller Bring, samt til EU og 3. lande igennem Bring, UPS eller andre efter kundens &oslash;nske. Cloud Router leverer alle solgte varer og tilknyttede ydelser til den tid, der fremg&aring;r af Cloud Routers ordrebekr&aelig;ftelse. Cloud Router har ret til at levere f&oslash;r den aftalte leveringstid, medmindre parterne har aftalt andet.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\">&emsp;</span><br /><span style=\"color: #333333;\">13. Forsinket levering og oph&aelig;velse</span><br /><span style=\"color: #333333;\">Hvis Cloud Router forventer en forsinkelse i leveringen af varer eller tilknyttede ydelser, informerer Cloud Router kunden om forsinkelsen og oplyser samtidig &aring;rsagen til forsinkelsen, samt ny forventet leveringstid. Hvis Cloud Router undlader at levere varer eller tilknyttede ydelser senest 14 dage efter den aftalte leveringstid af &aring;rsager, som kunden er uden ansvar for, og levering ikke sker inden en rimelig frist p&aring; mindst 7 dage, kan kunden oph&aelig;ve den eller de ordrer, der er ber&oslash;rt af forsinkelsen, uden varsel ved skriftlig meddelelse til Cloud Router. Kunden har ikke andre rettigheder i anledning af forsinket levering.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">14. Garanti</span><br /><span style=\"color: #333333;\">Cloud Router yder ikke selvst&aelig;ndig garanti p&aring; vareleverancer. Kunden kan ikke overfor Cloud Router rejse krav i henhold til en i k&oslash;bsaftalen eller p&aring; anden m&aring;de tilsagt producentgaranti for en vare, idet Cloud Router alene videreformidler en s&aring;dan producentgaranti til kunden.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">15. Mangler og reklamation</span><br /><span style=\"color: #333333;\">Ved modtagelse af en leverance skal kunden straks kontrollere de leverede varer fra Cloud Router. Hvis kunden vil p&aring;ber&aring;be sig en mangel, skal kunden, straks efter manglen er eller burde v&aelig;re opdaget, give Cloud Router skriftlig meddelelse herom, samt anf&oslash;rt hvori manglen best&aring;r. Har kunden ikke inden 3 m&aring;neder efter leveringsdato p&aring;ber&aring;bt sig manglen over for Cloud Router, kan kunden ikke senere g&oslash;re manglen g&aelig;ldende.</span><br /><span style=\"color: #333333;\">Reklamation skal ske straks efter en fejl eller mangel konstateres. Ombytning eller reparation medf&oslash;rer ikke, at der l&oslash;ber en ny reklamationsperiode p&aring;. Reklamation g&aelig;lder ikke, hvis fejlen skyldes produkter med fysiske skader eller skader der opst&aring;et p&aring; grund af lyn, statisk elektricitet, vand eller andet misbrug. Reklamation omfatter ikke software konfigurationer eller software tilpasninger.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">16. Ansvar for mangler</span><br /><span style=\"color: #333333;\">Cloud Router er kun ansvarlig for mangler, der skyldes fejl i produkter, og ikke for mangler, der kan henf&oslash;res til forkert behandling, installation, anvendelse eller opbevaring. Det er s&aring;ledes en betingelse for Cloud Routers ansvar, at kunden har anvendt varen efter forskrifterne og p&aring; forsvarlig m&aring;de samt if&oslash;lge Cloud Routers eventuelle anvisninger. Kunden henvises til at f&oslash;lge brugsvejledninger m.m., der er leveret med produktet, eller til selv at indhente de forn&oslash;dne oplysninger om korrekt anvendelsesm&aring;de og l&oslash;bende servicering af produktet.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\">Kunden b&aelig;rer selv risikoen for, at Cloud Routers leverance er egnet til form&aring;let, der er s&aelig;rligt g&aelig;ldende for kunden. Viser det sig, at produktet er beh&aelig;ftet med mangler, har Cloud Router ret til at foretage afhj&aelig;lpning eller ombytning efter eget valg. Kun s&aring;fremt Cloud Router ikke inden for rimelig tid og ved et rimeligt antal afhj&aelig;lpningsfors&oslash;g er i stand til at foretage afhj&aelig;lpning eller fejlretning, kan kunden kr&aelig;ve erstatning, hvis de almindelige erstatningsbetingelser er opfyldt. Dog begr&aelig;nses erstatningen til et bel&oslash;b svarende til omkostningerne ved at udbedre manglen og kan maks. andrage den aftalte k&oslash;besum.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">17. Ansvarsbegr&aelig;nsning</span><br /><span style=\"color: #333333;\">S&aring;fremt der m&aring;tte blive konstateret, mangler ved det leverede, er kunden alene berettiget til at kr&aelig;ve evt. mangler afhjulpet. Cloud Router har pligt til at afhj&aelig;lpe mangler. Hvis Cloud Router efter gentagne fors&oslash;g ikke kan afhj&aelig;lpe de konstaterede mangler, og kunden herved har lidt et direkte tab, er Cloud Router erstatningsansvarspligtig efter dansk rets almindelige regler.&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><br />18. Indirekte tab<br /></span><span style=\"color: #333333;\">Uanset eventuelle modst&aring;ende vilk&aring;r i Aftalegrundlaget er Cloud Router under ingen omst&aelig;ndigheder erstatningsansvarlig overfor kunden vedr&oslash;rende tab af produktion, salg, fortjeneste, tid, goodwill eller andre indirekte tab eller f&oslash;lgeskader, uanset om Cloud Router er blevet informeret om s&aring;danne kravs mulighed. Cloud Routers erstatningsansvar er uanset ansvarsgrundlag begr&aelig;nset til et bel&oslash;b, der ikke overstiger det bel&oslash;b, kunden har betalt for den mangelfulde leverance.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">19. Fortrydelsesret</span><br /><span style=\"color: #333333;\">Der er normalt ingen fortrydelsesret eller returret for erhvervskunder. I enkelte s&aelig;rlige tilf&aelig;lde tages retur/ombyttes efter forudg&aring;ende aftale og altid kun i v&aelig;sentlig stand samt i original emballage. Omkostninger i forbindelse med returnering, samt allerede opkr&aelig;vet fragtgebyr refunderes ikke. Endvidere forbeholder Cloud Router sig ret til at p&aring;ligge et h&aring;ndteringsgebyr p&aring; 250 kroner ekskl. moms.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">20. Force majeure</span><br /><span style=\"color: #333333;\">Hverken kunden eller Cloud Router kan i henhold til n&aelig;rv&aelig;rende aftale anses for ansvarlig over for den anden part, for s&aring; vidt ansvaret skyldes forhold, der ligger udenfor parternes kontrol. Force majeure ved forsinkelse kan h&oslash;jst g&oslash;res g&aelig;ldende med det antal arbejdsdage, som force majeure situationen varer. S&aring;fremt en tidsfrist for Cloud Router udskydes p&aring; grund af force majeure, udskydes de eventuelle betalinger der knytter sig hertil, tilsvarende. Den part, der ikke er ramt af force majeure situationen, er berettiget til at annullere den eller de aftaler, der er ber&oslash;rt af force majeure situationen, s&aring;fremt det har varet mere end 30 arbejdsdage.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">21. Fortrolighed</span><br /><span style=\"color: #333333;\">Kunden m&aring; ikke viderebringe, bruge eller s&aelig;tte andre i stand til at bruge Virksomhedens erhvervshemmeligheder eller andre oplysninger uanset art, som ikke er offentligt tilg&aelig;ngelige. Kunden m&aring; ikke p&aring; utilb&oslash;rlig m&aring;de skaffe sig eller fors&oslash;ge at skaffe sig kendskab til eller r&aring;dighed over Virksomhedens fortrolige oplysninger. Kunden skal omg&aring; og opbevare oplysningerne forsvarligt for at undg&aring;, at de utilsigtet kommer til andres kundskab. Kundens fortrolighedsforpligtelser g&aelig;lder under parternes samhandel og uden tidsbegr&aelig;nsning efter samhandlens oph&oslash;r uanset &aring;rsagen til oph&oslash;ret.</span></p>\r\n<p style=\"text-align: justify;\"><br /><span style=\"color: #333333;\">22. Uoverensstemmelser</span><br /><span style=\"color: #333333;\">Enhver retstvist mellem kunden og Cloud Router afg&oslash;res efter Dansk Ret ved de almindelige domstole.</span></p>', 1773, 'Cloud Router B2B salg og leveringsbetingelser', 'Cloud Router ApS B2B salg og leveringsbetingelser', '', '', '', 1),
(3, NULL, 'service', '<p><div class=\"meddelelse_boks center_container\"><span style=\"color:red;\">Siden blev desværre ikke fundet. Du bliver viderestillet til forsiden.</span></div>\r\n</p>\r\n<script type=\"text/javascript\">setTimeout(\"location.href=\'index.php\';\",2000);</script>', 1924, '', '', '', '', '', 1),
(4, 'produkter', 'Products DK', '<h3><span style=\"color: #339966;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Professional </span></span><span><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">sales advice</span></span></span></span></h3>\r\n<p><span><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">As a customer of Cloud Router, you get professional help in choosing products.</span></span></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">⨠</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> Create a sales case via </span></span></span><a title=\"Cloud Router Online form\" href=\"http://www.cloudrouter.dk/service\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">O</span></span></span><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> nline form</span></span></span></a></p>\r\n<p><span style=\"color: #000000;\"><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">⨠&nbsp;</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> Send an email to sales[@]cloudrouter.dk</span></span></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">If you are not yet a customer with us, you can read about our dealer program on the </span></span><span style=\"color: #0000ff;\"><a title=\"Cloud Router Reseller Program\" href=\"forhandler\"><span style=\"color: #0000ff;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">dealer</span></span></span></a><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> page .</span></span></span></span></p>\r\n<p>&nbsp;</p>', 41324, 'Cloud Router - WiFi, trådløs backbone, radio-link og IoT produkter', 'Leverandør af WiFi, trådløs backbone, radio-link og IoT netværksprodukter', 'WiFi, WLAN bridge, trådløs bro, Firewall, Router, Ethernet, PoE, Switch, M2M, IoT, trådløst netværk', '', '', 1),
(5, 'sitemap', 'sitemap', '<div style=\"font: bold 15px trebuchet ms,verdana,helvetica,sans-serif; margin-top: 0; color: #436D9B;\">Sitemap</div>\r\n<p>&nbsp;</p>', 449, '', '', '', '', '', 1),
(8, 'forside_2', 'forside_2', '<h1><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Strength</span></span></span></span></h1>\r\n<p style=\"text-align: justify;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">With our different backgrounds and strong relationships with recognized manufacturers, we get the opportunity to anticipate upcoming technological changes on the market.</span></span></span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Our driving force in Cloud Router is a long-term collaboration between our customers and partners, and is based on knowledge and innovation.</span></span></span></span></p>', 0, '', '', '', '', '', 1),
(9, NULL, 'betingelser_b2b', 'Her kommer snart betingelser.', 0, '', '', '', '', '', 1),
(10, NULL, 'forside_b2b', '<div style=\"font: bold 15px trebuchet ms,verdana,helvetica,sans-serif; margin-top: 0; color: #436D9B;\">Velkommen til Santronics\' b2b shop</div>', 0, '', '', '', '', '', 1),
(11, 'producentmap', 'Vendor-map DK', '<div style=\"font: bold 15px trebuchet ms,verdana,helvetica,sans-serif; margin-top: 0; color: #436d9b;\">Producenter</div>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', 0, 'Cloud Routers producenter', 'Cloud Routers producenter', 'Cloud Routers producenter', '', '', 1),
(12, 'point-to-point', 'Punkt til Punkt trådløs Bridge', '<h1 style=\"text-align: center;\"><span style=\"color: #3366ff; font-size: x-large;\">Tr&aring;dl&oslash;s Bridge og Radio Link</span></h1>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: center;\"><img style=\"width: 633px; height: 290px;\" title=\"Cloud Router Radio-link\" src=\"docs/LigoWave/LigoWave_Rapidfire_profil.png\" alt=\"Cloud Router Radio-link\" width=\"1102\" height=\"511\" /></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Radio-link og tr&aring;dl&oslash;s bridge benyttes til at danne forbindelser mellem netv&aelig;rksenheder p&aring; to eller flere lokationer</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Vi leverer alt fra licensfri 5GHz til 80GHz l&oslash;sninger, der kan erstatte fibergravning med 99,99 % driftssikkerhed</span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\"><img style=\"width: 449px; height: 207px;\" title=\"Cloud Router tr&aring;dl&oslash;s bridge\" src=\"docs/LigoWave/WLAN_bridge.png\" alt=\"Cloud Router tr&aring;dl&oslash;s bridge\" width=\"495\" height=\"200\" />&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img style=\"width: 422px; height: 218px;\" title=\"Cloud Router CCTV link\" src=\"docs/Siklu/CCTV_link.png\" alt=\"Cloud Router CCTV link\" width=\"1062\" height=\"658\" /></span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\"><span style=\"color: #339966; font-size: medium;\">Benyttes til data&nbsp;forbindelser mellem bygninger, HD videokameraer og WiFi netv&aelig;rk samt forl&aelig;ngelse af fiber</span></span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\"><img style=\"width: 529px; height: 232px;\" title=\"Cloud Router Tr&aring;dl&oslash;s fiber\" src=\"docs/Siklu/Fiber_net.png\" alt=\"Cloud Router Tr&aring;dl&oslash;s fiber\" width=\"1017\" height=\"363\" />&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;<img style=\"width: 389px; height: 269px;\" title=\"Cloud Router tr&aring;dl&oslash;s backbone\" src=\"docs/Siklu/Siklu_backbone.png\" alt=\"Cloud Router tr&aring;dl&oslash;s backbone\" width=\"568\" height=\"420\" /></span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\"><span style=\"color: #339966; font-size: medium;\">Benyttes bl.a. af virksomheder, havne, lufthavne, trafiksektorer, internetudbydere og af det offentlige</span></span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Kontakt os venligst for yderligere information.</span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p>&nbsp;</p>', 0, '', '', '', '', '', 1),
(13, 'firewall-og-router', 'Firewall og router', '<h1 style=\"text-align: center;\"><span style=\"color: #3366ff; font-size: x-large;\">Netv&aelig;rkssikkerhed</span></h1>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: center;\"><img style=\"width: 857px; height: 356px;\" title=\"Cloud Router Firewall\" src=\"docs/Endian/Company.png\" alt=\"Cloud Router Firewall\" width=\"1200\" height=\"600\" /></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Vores l&oslash;sning beskytter netv&aelig;rket mod hackere, inficering via web, mail og applikationer hos virksomheder</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Derudover forhindres ogs&aring;&nbsp;sikkerhedstrusler og angreb lige som en sikkerhedskontrol i en lufthavn.</span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><a title=\"Endian UTM funktioner\" href=\"http://www.endian.com/products/utm/\" target=\"_blank\"><img style=\"width: 1101px; height: 314px;\" title=\"Liste over alle Endian funktioner\" src=\"docs/endian/Endian_utm_key.png\" alt=\"Endian UTM features\" width=\"1582\" height=\"445\" /></a>&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Intelligent netv&aelig;rkssikkerhed med den rette balance mellem pris og funktioner.</span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: left;\"><a title=\"Endian produkter og priser\" href=\"index.php?p=sortering1&amp;gruppe=Router_-_Firewall\" target=\"_blank\"><img style=\"margin-right: auto; margin-left: auto; display: block;\" title=\"Endian produkter og priser\" src=\"docs/Endian/Endian_Appliances.png\" alt=\"Endian Firewall Appliances\" /></a>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"font-size: small;\">&nbsp;<span style=\"color: #339966;\">Endian Hardware Appliances &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;Endian Software Appliance &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; &nbsp; Endian Virtual Appliance</span></span></p>\r\n<p style=\"text-align: center;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">&nbsp;Firewall og router l&oslash;sningerne f&aring;s som hardware, software eller virtual platform med Cloud administration.</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Kontakt os venligst for yderligere information.</span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>', 0, '', '', '', '', '', 1),
(14, 'wifi-netvaerk', 'WiFi netværk', '<h1 style=\"text-align: center;\"><span style=\"color: #3366ff; font-size: x-large;\">WiFi Tr&aring;dl&oslash;st Netv&aelig;rk</span></h1>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><img title=\"Cloud Router WiFi\" src=\"docs/emplus/Emplus.png\" alt=\"Cloud Router WiFi\" width=\"911\" height=\"241\" />&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;&nbsp;&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">&nbsp;</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">&nbsp;Vores l&oslash;sninger tager udgangspunkt i intelligente funktioner som virksomheder og skoler har behov for</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #339966; font-size: medium;\">Vi&nbsp;leverer driftsikre og h&oslash;jtydende netv&aelig;rksprodukter med moderne og innovativ teknologi</span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><img style=\"width: 929px; height: 382px;\" title=\"Cloud Router WiFi\" src=\"docs/emplus/Emplus_banner.png\" alt=\"Cloud Router WiFi\" width=\"1105\" height=\"476\" /></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><span style=\"color: #339966;\"><span style=\"color: #339966;\">L&oslash;sningerne skalerer lige fra Stand-alone, Controller baseret, til Cloud management med mobil applikation.</span></span></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><span style=\"color: #339966;\"><span style=\"color: #339966;\">Kontakt os venligst for yderligere&nbsp;information.</span></span></span></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>', 0, '', '', '', '', '', 1),
(15, 'service', 'Teknisk support', '<p>Teknisk support d&aelig;kker alt lige fra ops&aelig;tning af udstyr, til &aelig;ndringer af konfigurationer og fejlfinding. Teknisk support faktureres pr. p&aring;begyndt kvarter ved fjernsupport, dog pr. p&aring;begyndt time ved on-site assistance.</p>\r\n<p><strong><br />&bull;&nbsp;</strong>Opret en sag i vores system via&nbsp;Online-formularen</p>\r\n<p><strong>&bull;&nbsp;</strong>Send en mail til&nbsp;support[@]cloudrouter.dk&nbsp;med kort info om jeres behov</p>\r\n<p><strong>&bull;&nbsp;</strong>Ring til vores kontor for at oprette en sag</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Priser<br /></strong></p>\r\n<p>Support via telefon / internet pr. p&aring;begyndt kvarter&nbsp; &nbsp; &nbsp;ekskl. Moms kr. 200,-</p>\r\n<p>Support ude hos kunden, pr. p&aring;begyndt time&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;ekskl. Moms kr. 800,-</p>\r\n<p>Transportudgifter pr. km&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ekskl. Moms kr. 4,-</p>\r\n<p>Forhandlere og installat&oslash;rer kan opn&aring; 20 % rabat p&aring; timepriser.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Teknisk support til CloudஃWiFi kunder</strong></p>\r\n<p>Har du en gyldig CloudஃWiFi aftale, leveres remote teknisk support uden omkostning, samt begr&aelig;nset remote teknisk support til ops&aelig;tning af brugerenheder.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Reklamation</strong></p>\r\n<p style=\"text-align: justify;\"><span>St&aring;r du med et&nbsp;ikke funktionsdygtigt&nbsp;produkt, bes&oslash;g venligst&nbsp;</span><span style=\"color: #0000ff;\"><a title=\"RMA vejledning\" href=\"https://drive.google.com/file/d/1re24pwGg-xkyB-TDcJ5ex8UdBTO_F7YF/view\" target=\"_blank\"><span style=\"color: #0000ff;\">RMA&nbsp;vejledning.</span></a><span style=\"color: #0000ff;\"><br /></span></span><span style=\"font-size: 1em;\">Kontakt os for yderligere information.</span></p>', 0, 'Salgsrådgivning, sparring og teknisk assistance - Cloud Router', 'Cloud Router tilbyder professionel assistance og sparring til WLAN og trådførte netværksløsninger.', 'professionel assistance, sparring, rådgivning, help desk', '', '', 1),
(16, 'forhandler', 'Bliv forhandler', '<p>IT-forhandlere og installat&oslash;rer, internetudbydere og teleselskaber kan blive forhandler af Cloud Routers produkter.</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Autoriseret forhandler <br /></strong>Cloud Routers autoriseret-forhandler-program er udviklet i t&aelig;t samarbejde med producenterne. P<span>rogrammet&nbsp;</span>kan med fordele&nbsp;v&aelig;re med til at &oslash;ge forretningsekspertise og markedsmuligheder for alle parter.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p><strong>Hvorfor?<br /></strong>&bull;&nbsp;Bedste priser p&aring; produkter<br />&bull;&nbsp;Teknisk kvalificeret personale<br />&bull;&nbsp;Succesfulde implementeringer<br />&bull;&nbsp;Nye og bedre l&oslash;snings- og markedsmuligheder</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Hvordan?<br /></strong></p>\r\n<p style=\"text-align: justify;\">En salgskonsulent hos partneren skal deltage i en kort produktgennemgang hvert halve &aring;r.&nbsp;Produktgennemgangen foreg&aring;r som regel ved at deltage i et af vores &aring;bent hus-arrangementer.&nbsp;<span style=\"text-align: justify;\">En netv&aelig;rkskonsulent skal gennemg&aring; et &aring;rligt tr&aelig;ningskursus, for den aktuelle produktserie. Tr&aelig;ningskurset afsluttes med online eksamen, hvor konsulenten kan opn&aring; et certificeringsbevis. Certificeringsbeviset g&aelig;lder i et &aring;r og skal fornyes hvert &aring;r. Tilmelding: sendes til </span><a style=\"text-align: justify;\" href=\"mailto:salg@cloudrouter.dk\">salg@cloudrouter.dk</a></p>\r\n<p style=\"text-align: justify;\"><a href=\"mailto:salg@cloudrouter.dk\"><br /><span style=\"color: #000000;\">Se mere p&aring; Cloud Routers&nbsp;</span></a><a title=\"Bes&oslash;g Cloud Routers blog for projekter, forslag og vejledninger\" href=\"https://blog.cloudrouter.dk/\" target=\"_blank\">Blog</a><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #000000;\">,&nbsp;</span></a><a title=\"Bes&oslash;g Cloud Routers Linkedin profil\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #000000;\">&nbsp;og&nbsp;</span></a><a title=\"Bes&oslash;g Cloud Routers Twitter profil\" href=\"https://twitter.com/Cloudrouter_dk\" target=\"_blank\">Twitter</a><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #000000;\">&nbsp;profiler.</span></a></p>', 0, 'Forhandlerprogram med registreret og autoriseret forhandlerniveauer', 'Cloud Routers forhandlerprogram består af registreret og autoriseret forhandlerniveauer', 'forhandlerprogram, Registreret forhandler, autoriseret forhandler, IT forhandler, udbyder, systemintegrator, installatør, el installatør, kamera installatør, CCTV installatør', '', '', 1),
(30, 'references', 'Cases DK', '<p style=\"text-align: justify;\">Som kunde kan du leve dine ambitioner ud i en international kultur sammensat af topprofessionelle folk, som deler passionen for datakommunikation.&nbsp;<span>&nbsp;Vi har fokus p&aring; at skabe gode og <span>us&aelig;dvanlige&nbsp;</span>resultater sammen med vores kunder, som har de strengeste krav til investering, kvalitet og driftssikkerhed.</span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h4>Udpluk af vores forhandler-partnere</h4>\r\n<p style=\"text-align: justify;\">&bull; Burmeister &amp; Wain - global leverand&oslash;r af Energyplant l&oslash;sninger</p>\r\n<p style=\"text-align: justify;\">&bull;&nbsp;Seesafe -&nbsp;professionel leverand&oslash;r af HD videooverv&aring;gning</p>\r\n<p style=\"text-align: justify;\">&bull;&nbsp;KM Telcom -&nbsp;leverand&oslash;r af WiFi, WTTx og LTE&nbsp;l&oslash;sninger til udbydere</p>\r\n<p style=\"text-align: justify;\">&bull; Lindpro A/s - leverand&oslash;r professionelle&nbsp;sikring- og netv&aelig;rksl&oslash;sninger</p>\r\n<p style=\"text-align: justify;\">&bull;&nbsp;Compusoft A/s -&nbsp;leverand&oslash;r af&nbsp;professionelle l&oslash;sninger til&nbsp;feriesteder</p>\r\n<p style=\"text-align: left;\"><span>&bull;&nbsp;KK Partner -&nbsp;leverand&oslash;r af&nbsp;professionelle l&oslash;sninger til&nbsp;antenneforeninger</span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h4><span style=\"color: #000000;\">Samarbejde skaber v&aelig;rdier</span></h4>\r\n<p style=\"text-align: justify;\">Cloud Router arbejder m&aring;lrettet p&aring; at leve op til de forventninger vores kunder har til os. Vi har en hands-on tilgang og st&aelig;rkt fokus p&aring; at introducere nye og bedre l&oslash;sningsmuligheder.<br /><br />Se mere p&aring; Cloud Routers&nbsp;<a title=\"Bes&oslash;g Cloud Routers blog for projekter, forslag og vejledninger\" href=\"https://blog.cloudrouter.dk/\" target=\"_blank\">Blog</a>,&nbsp;<a title=\"Bes&oslash;g Cloud Routers Linkedin profil\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a>&nbsp;og&nbsp;<a title=\"Bes&oslash;g Cloud Routers Twitter profil\" href=\"https://twitter.com/Cloudrouter_dk\" target=\"_blank\">Twitter</a>&nbsp;profiler.</p>', 0, 'Cloud Router kundereferencer', 'Se vores fantastiske kundereferencer', 'WiFi referencer, WLAN referencer, netværks installation referencer, IT referencer', '', 'profile', 1),
(17, 'rma', 'RMA DK', '<h2>Produkter omfattet af reklamation</h2>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\">Fejlmelding p&aring; et defekt produkt omfattet af reklamation modtages kun via vores support e-mail.</span></p>\r\n<p><span style=\"color: #333333;\">Vi beder dig venligst sende en e-mail til</span><span style=\"color: #333333;\"> <span style=\"color: #0000ff;\"><a href=\"mailto:service@cloudrouter.dk\"><span style=\"color: #0000ff;\">service[snabela]cloudrouter.dk</span></a></span> </span><span style=\"color: #333333;\">med f&oslash;lgende:</span></p>\r\n<p><span style=\"color: #333333;\"><span style=\"color: #000000;\"><br /></span></span></p>\r\n<p><span style=\"color: #333333;\">&bull; Kort beskrivelse af den oplevede fejl og evt. &aring;rsag</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Fakturanummer, modelnummer og&nbsp;<span>serienummer </span>p&aring; produktet</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\">Kontaktpersonen vil modtage en bekr&aelig;ftelse med et RMA-nummer, n&aring;r</span><span style=\"color: #333333;\">&nbsp;vi registrerer jeres RMA-sag i vores system.</span></p>\r\n<p><span style=\"color: #333333;\">Et defekt produkt som er d&aelig;kket af standard Reklamation, skal returneres til Cloud Router f&oslash;r sagen kan behandles.</span></p>\r\n<p><span style=\"color: #333333;\">Det defekte produkt repareres eller ombyttes inden for 5 &ndash; 30 dage fra modtagelsen.</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #ff0000;\">Reklamation omfatter et produkt k&oslash;bt hos Cloud Router, hvis produktet ikke er funktionsdygtigt,<br />selv om produktet er konfigureret og installeret efter&nbsp;producentens anvisninger.</span></p>\r\n<div>&nbsp;</div>\r\n<p>&nbsp;</p>\r\n<h2>Produkter omfattet af SLA</h2>\r\n<p><span style=\"color: #333333;\">Fejlmelding p&aring; produkter omfattet af SLA, modtages kun via&nbsp;vores support e-mail.</span></p>\r\n<p><span style=\"color: #333333;\">Vi beder dig venligst sende en e-mail til&nbsp;<span style=\"color: #0000ff;\"><a href=\"mailto:service@cloud-router.dk\"><span style=\"color: #0000ff;\">service[snabela]cloudrouter.dk</span></a></span>&nbsp;med f&oslash;lgende:</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Kort fejlbeskrivelse og evt. &aring;rsag</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Fakturanummer eller Service ID</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Serie- og modelnummer p&aring; produktet</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\">Sagen p&aring;begyndes inden for 1 - 4 timer fra fejlmeldingen og vi orienterer kontaktpersonen l&oslash;bende om sagens forl&oslash;b.<br /></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">Hvis du &oslash;nsker r&aring;dgivning til implementering for et produkt k&oslash;bt med SLA, skal der ved henvendelse altid oplyses faktura- og serienummer&nbsp;p&aring; produktet.</span><br /><span style=\"color: #ff0000;\">SLA omfatter alene hardwarefejl, eller et produkt der ikke er funktionsdygtigt, selv om produktet er konfigureret og installeret efter producentens anvisninger. </span><br /><span style=\"color: #ff0000;\">SLA omfatter ikke softwarekonfigurationer eller fejl opst&aring;et pga. softwaretilpasninger og fejlkonfigurationer.&nbsp;</span><span style=\"color: #0000ff;\"><a title=\"Hardware support - SLA brochure\" href=\"https://drive.google.com/file/d/1D5ileoJz1prVvaL7KNEprLIFil-_HibX/view\" target=\"_blank\"><span style=\"color: #0000ff;\">L&aelig;s mere</span></a></span></p>\r\n<div><span><br /></span></div>\r\n<p>&nbsp;</p>\r\n<h2><span>Reklamation og SLA omfatter ikke f&oslash;lgende:</span></h2>\r\n<p><span style=\"color: #333333;\">&bull; Fysisk sliddele som kan have en begr&aelig;nset levetid.<br /></span><span style=\"color: #333333;\">&bull; Konfigurationer eller justeringer af k</span><span style=\"color: #333333;\">onfigurationer.<br /></span><span style=\"color: #333333;\">&bull; Skade opst&aring;et som f&oslash;lge af forkert vedligeholdelse.<br /></span><span style=\"color: #333333;\">&bull; Visuelle skader som ikke ber&oslash;rer en fabrikationsfejl.<br /></span><span style=\"color: #333333;\">&bull; Omkostninger i forbindelse med tabt arbejdsfortjeneste, v&aelig;rditab, produktnedbrud eller anden omkostning.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #ff0000;\">Produkterne kr&aelig;ver professionel&nbsp;installation og konfiguration og&nbsp;i nogle&nbsp;</span><span style=\"color: #ff0000;\">tilf&aelig;lde af en certifeceret konsulent.&nbsp;</span></p>\r\n<p><span style=\"color: #ff0000;\">Produkter der ikke er <span>installeret og&nbsp;</span>konfigureret <span>korrekt</span>, er udenfor Cloud Routers&nbsp;ansvar.</span></p>', 0, 'Cloud Router - RMA og garanti ydelser', 'Clour Router assisterer og supporterer netværksløsninger herunder Firewall, Radio-Link, WiFi, Industrielt netværk, Ethernet og meget andet.', '', '', '', 1),
(18, 'forside_3', 'Forside 3', '<h1>V&aelig;rdier</h1>\r\n<p>Som vidensbaseret datakommunikationsvirksomhed ser&nbsp;vi det som vores ansvar, at v&aelig;re&nbsp;med til at udvikle og fremtidssikre vores&nbsp;samfund.</p>\r\n<p style=\"text-align: justify;\"><br />Cloud Routers intention er at skabe kontinuerlig v&aelig;rdi for alle nuv&aelig;rende og kommende kunder, p&aring; hele det nordiske marked.</p>', 0, '', '', '', '', '', 1),
(19, 'wireless-network', 'WiFi network DK', '<h2>H&oslash;jtydende WiFi</h2>\r\n<p style=\"text-align: justify;\">Cloud Router leverer en af de mest attraktive WiFi l&oslash;sninger p&aring; markedet, med <span>robuste indend&oslash;rs og udend&oslash;rs Access punkter</span>. Udover central management og h&oslash;j sendestyrke, har vores WiFi l&oslash;sning intelligente funktioner, for at kunne opretholde et stabilt og&nbsp;h&oslash;jtydende WiFi netv&aelig;rk.</p>\r\n<p>&nbsp;</p>\r\n<h2>D&aelig;kning til h&aring;ndholdte</h2>\r\n<p style=\"text-align: justify;\">H&aring;ndholdte enheder, mobiltelefoner og tablets har som regel en mindre sendestyrke i forhold til Access punkterne. Cloud Router leverer WiFi Access punkter, der b&aring;de har&nbsp;h&oslash;j sendestyrke og forbedret f&oslash;lsomhed p&aring; modtagersiden,&nbsp;hvilket&nbsp;giver den optimale d&aelig;kning til h&aring;ndholdte enheder.</p>\r\n<p>&nbsp;</p>\r\n<h2>Managed WiFi</h2>\r\n<p style=\"text-align: justify;\">Cloud Routers WiFi l&oslash;sning kan udrulles og installeres, uden at de enkelte Access punkter skal klareg&oslash;res af en&nbsp;<span>netv&aelig;rkstekniker. Med vores WiFi l&oslash;sning&nbsp;</span>kan et <span>h&oslash;jtydende&nbsp;WiFi netv&aelig;rk&nbsp;</span>implementeres uanset st&oslash;rrelse, lokation og <span>kundetype</span>.&nbsp;Udover det danske&nbsp;Panther-admin <span>system&nbsp;</span>kan&nbsp;vores WiFi l&oslash;sning administreres via In-AP Controller, On-premises eller Cloud management. Se mere p&aring; Cloud Routers&nbsp;<a title=\"Bes&oslash;g Cloud Routers blog for projekter, forslag og vejledninger\" href=\"https://blog.cloudrouter.dk/\" target=\"_blank\">Blog</a>,&nbsp;<a title=\"Bes&oslash;g Cloud Routers Linkedin profil\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a>&nbsp;og&nbsp;<a title=\"Bes&oslash;g Cloud Routers Twitter profil\" href=\"https://twitter.com/Cloudrouter_dk\" target=\"_blank\">Twitter</a>&nbsp;profiler.</p>', 0, 'Stabilt og højtydende WiFi trådløst netværk - Cloud Router', 'Højtydende og managed WiFi netværk til indendørs og udendørs installationer. ', 'WiFi, trådløst netværk, stabilt WiFi, WLAN, skole WiFi, WiFi camping, WiFi sommerhuse, WiFi udendørs, cloud WiFi, Aruba WiFi, Ruckus WiFi, Aerohive WiFi, Meru Networks, Zen systems, Sec datacom, netdesign, atea', '', 'forretningsomraader', 1),
(20, 'radio-link', 'Radio-link DK', '<h2>Tr&aring;dl&oslash;se radiolinks</h2>\r\n<p style=\"text-align: justify;\">Cloud Routers tr&aring;dl&oslash;se punkt-til-punkt og multipunkt l&oslash;sninger kan erstatte traditionelle kobber og fibergravninger. Vi leverer en omfattende portef&oslash;lje af 5GHz licensfri radiolinks, 3 &ndash; 6GHz licenserede radiolinks, samt 7 &ndash; 80GHz fuld-dupleks radiok&aelig;de, som kan supplere fibergravninger og fiberforl&aelig;ngelser.<br /><br /></p>\r\n<h2>5GHz radiolinks</h2>\r\n<p style=\"text-align: justify;\">Cloud Routers 5GHz produktsortiment er n&oslash;je udvalgt, af specialister med&nbsp;over 20 &aring;rs <span>erfaring&nbsp;</span>indenfor tr&aring;dl&oslash;s datakommunikation. Vores 5GHz punkt-til-punkt og multipunkt produkter har den h&oslash;jeste kvalitet og bedste ydeevne, desuden enkle modeller til en attraktiv pris &ndash; alt sammen ud fra anvendelsesform&aring;l og behov.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2><span>Full-duplex&nbsp;</span>radiok&aelig;de</h2>\r\n<p style=\"text-align: justify;\"><span>Kun det bedste er godt nok. Vi udstyrer vores kunder med fuld-dupleks radiok&aelig;de&nbsp;</span><span>fra den verdenskendte producent Ceragon Networks. Fuld-dupleks&nbsp;<span>dataoverf&oslash;rsel med&nbsp;</span></span>0,1ms i latency er de egenskaber Ceragon <span>radiok&aelig;de&nbsp;</span>p&aring; 7, 10, 15, 18, 23 og 80GHz tilbyder.&nbsp;Fuld-dupleks <span>radiok&aelig;de&nbsp;</span>har lavere anl&aelig;gsinvesteringer og driftsomkostninger, sammenlignet med nedgravede l&oslash;sninger.&nbsp;Derudover en meget kort implementeringstid.<br /><br /></p>\r\n<p style=\"text-align: justify;\">Se mere p&aring; Cloud Routers&nbsp;<a title=\"Bes&oslash;g Cloud Routers blog for projekter, forslag og vejledninger\" href=\"https://blog.cloudrouter.dk/\" target=\"_blank\">Blog</a>,&nbsp;<a title=\"Bes&oslash;g Cloud Routers Linkedin profil\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a>&nbsp;og&nbsp;<a title=\"Bes&oslash;g Cloud Routers Twitter profil\" href=\"https://twitter.com/Cloudrouter_dk\" target=\"_blank\">Twitter</a>&nbsp;profiler.</p>', 0, 'WLAN bridge, Radiolink og Multipoint løsninger - Cloud Router', 'Førende leverandør af trådløs bridge, radio-link og WLAN multi-point løsninger.', 'Wireless bridge, radio link, trådløs bridge, Ubiquiti, NSM5, UBNT, punkt-til-punkt, 5GHz link, Wireless link, Wireless data, Winther Wireless, trådløs bro, bridge, WLAN bridge', '', 'forretningsomraader', 1),
(29, 'unsubscribe-newsletter', 'Unsubscribe DK', '<h2><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Submit newsletter</span></span></h2>\r\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">If you no longer wish to receive our newsletter, you can unsubscribe below.</span></span></p>\r\n<p>&nbsp;</p>', 0, 'Frameld nyhedsmail', '', '', '', '', 1);
INSERT INTO `san_shop_sider` (`id`, `identifier`, `titel`, `indhold`, `count`, `search_title`, `search_meta_desc`, `search_meta_tags`, `contact_text`, `belongs_to`, `language_id`) VALUES
(21, 'network-security', 'Infrastructure DK', '<h2>Driftssikkerhed</h2>\r\n<p style=\"text-align: justify;\">Vi har fokus p&aring; at levere Ethernet produkter med h&oslash;j driftssikkerhed, der kan im&oslash;dekomme forventningerne hos virksomheder og u<span>dbydere.</span></p>\r\n<p>&nbsp;</p>\r\n<h2>Remote-arbejdsplads</h2>\r\n<p style=\"text-align: justify;\">Vores router- og firewall l&oslash;sninger kan h&aring;ndtere alle type af moderne opkoblingsmuligheder, s&aring;ledes at medarbejdere nemt kan udf&oslash;re deres arbejde uanset lokation.</p>\r\n<p style=\"text-align: justify;\"><span><br /></span></p>\r\n<h2>SLA</h2>\r\n<p style=\"text-align: justify;\"><span>Cloud Router tilbyder SLA ydelser p&aring; netv&aelig;rksprodukter. SLA best&aring;r af udvidet garanti, softwareopdateringer og teknisk assistance.<br /><br /><span>Se mere p&aring; Cloud Routers&nbsp;</span><a title=\"Bes&oslash;g Cloud Routers blog for projekter, forslag og vejledninger\" href=\"https://blog.cloudrouter.dk/\" target=\"_blank\">Blog</a><span>,&nbsp;</span><a title=\"Bes&oslash;g Cloud Routers Linkedin profil\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a><span>&nbsp;og&nbsp;</span><a title=\"Bes&oslash;g Cloud Routers Twitter profil\" href=\"https://twitter.com/Cloudrouter_dk\" target=\"_blank\">Twitter</a><span>&nbsp;profiler.</span></span></p>\r\n<p style=\"text-align: justify;\"><span><br /></span></p>', 0, 'Firewall og IT netværkssikkerhed til virksomheder - Cloud Router', 'IT netværkssikkerhed til virksomheder, secure browsing, applikations angreb, server angreb, insider trusler, hackere, malware, virus, m.m.', 'Next Gen Firewall, Next Generation Firewall, layer-7 firewall, secure browsing, applikationskontrol, filter facebook, filter p2p, blok web, netværkssikkerhed, IT sikkerhed, Firewall, check point, sonicwall, barracuda, Fortinet', '', 'forretningsomraader', 1),
(22, 'ethernet-network', 'M2M communications DK', '<h2>M2M kommunikation</h2>\r\n<p style=\"text-align: justify;\">Maskine-til-maskine kommunikation har &aelig;ndret vores digitale verden, fra at vi tidligere benyttede teknologi som et kommunikationsmiddel mellem mennesker, til i dag hvor udstyr kan tale med hinanden.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h2><span>Industrielt netv&aelig;rk</span></h2>\r\n<p style=\"text-align: justify;\">Vi tilbyder en r&aelig;kke industrielle produkter af h&oslash;j kvalitet med specifikke certificeringer, der lever op til de industrielle standarder. F.eks. 4G / LTE gateway, industrielle firewalls, radiolinks og Ethernet udstyr, som anvendes hos industrielle virksomheder.<br /><br />Cloud Router arbejder l&oslash;bende p&aring; at f&oslash;lge udviklingen inden for M2M og IoT l&oslash;sninger, s&aring;ledes at&nbsp;vi kan markedsf&oslash;re produkter med <span>den rette teknologi og med&nbsp;<span>h&oslash;j kvalitet</span></span>.<br /><br />Se mere p&aring; Cloud Routers&nbsp;<a title=\"Bes&oslash;g Cloud Routers blog for projekter, forslag og vejledninger\" href=\"https://blog.cloudrouter.dk/\" target=\"_blank\">Blog</a>,&nbsp;<a title=\"Bes&oslash;g Cloud Routers Linkedin profil\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a>&nbsp;og&nbsp;<a title=\"Bes&oslash;g Cloud Routers Twitter profil\" href=\"https://twitter.com/Cloudrouter_dk\" target=\"_blank\">Twitter</a>&nbsp;profiler.</p>', 0, 'Ethernet switch, fiber, industriel M2M og 4G løsninger - Cloud Router', 'PoE switch, fiber switch, firewall, router, M2M og 4G produkter med høj ydeevne og bred vifte af funktioner', '4G, 3G, LTE, PoE, Switch, M2M, IoT, fiber, Ethernet, Gigabit, 10Gigabit, backbone, datacenter, data netværk, it netværk, krydsfelt,', '', 'forretningsomraader', 1),
(23, 'uddannelse_1', 'Åbent hus arrangementer', '<p style=\"text-align: justify;\">V&aelig;r med til at styrke din virksomhed, gennem markedets mest innovative kommunikationsl&oslash;sninger. Cloud Router afholder &aring;bent hus arrangementer, med fremvisning af produkter og tr&aring;dl&oslash;se l&oslash;sninger fire gange om &aring;ret.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Administrerbar&nbsp;WiFi til bolig- og <strong>antenne</strong>foreninger</strong></p>\r\n<p style=\"text-align: justify;\">Gennemgang af vores h&oslash;jtydende og <span>administrerbare&nbsp;</span>WiFi til antenne- og boligforeninger. H&oslash;r hvordan Cloud Routers WiFi&nbsp;<span>afhj&aelig;lper&nbsp;</span>de udfordringer, der er p&aring; et WiFi netv&aelig;rk i private hjem.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p><strong><strong>Indend&oslash;rs og udend&oslash;rs&nbsp;</strong>WiFi <strong>l&oslash;sning&nbsp;</strong>til virksomheder&nbsp;</strong></p>\r\n<p style=\"text-align: justify;\"><span>Gennemgang af vores Cloud</span>WiFi l&oslash;sning. Information om hvordan virksomheder, skoler og offentlige institutioner kan implementere et&nbsp;<span>h&oslash;jtydende og&nbsp;</span><span>stabilt WiFi netv&aelig;rk.</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Tr&aring;dl&oslash;s backbone for WiFi og CCTV&nbsp;installationer&nbsp;</strong></p>\r\n<p style=\"text-align: justify;\"><span>Gennemgang af</span>&nbsp;<span>tr&aring;dl&oslash;se&nbsp;</span><span><span>Punkt-til-punkt og multipunkt l&oslash;sninger. L&aelig;r hvordan l&oslash;sningerne kan anvendes som&nbsp;</span></span>backbone for udend&oslash;rs WiFi installationer og CCTV kamera&nbsp;installationer.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>WTTx bredb&aring;ndsl&oslash;sning og&nbsp;fuld-dupleks&nbsp;<span>radiok&aelig;de</span></strong></p>\r\n<p style=\"text-align: justify;\"><span>Gennemgang af</span><span>&nbsp;WTTx tr&aring;dl&oslash;s bredb&aring;nd</span>&nbsp;og <span>fuld-dupleks <span>radiok&aelig;de l&oslash;sninger</span>. Information om hvordan <span>3 - 6GHz&nbsp;</span>WTTx <span>bredb&aring;ndsl&oslash;sning</span><span>&nbsp;</span><span>og&nbsp;</span><span>7 - 80GHz <span>radiok&aelig;de&nbsp;<span>kan&nbsp;</span></span></span></span><span>supplere coax- og fibergravninger.</span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p>Tidspunkter for <span>&aring;bent hus arrangementer</span>&nbsp;kan ses p&aring;&nbsp;<a style=\"text-align: justify;\" title=\"Kommende events\" href=\"http://www.cloudrouter.dk/events\">Kommende events</a><span style=\"color: #333333; text-align: justify;\">.</span></p>', 0, '', '', '', '', '', 1),
(24, 'uddannelse_2', 'Certificering og netværkskurser ', '<p style=\"text-align: justify;\"><span>Kurserne for dem, der &oslash;nsker at styrke deres kompetence p&aring; et h&oslash;jt og kvalificeret niveau inden for tr&aring;dl&oslash;se datakommunikation. Uddannelsen afsluttes med en online eksamen.&nbsp;</span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Certificeringskurser</strong></p>\r\n<p style=\"text-align: justify;\">&bull;&nbsp;LigoWave Infinity WiFi hands-on&nbsp;certificeringskursus&nbsp;</p>\r\n<p style=\"text-align: justify;\"><span>&bull;&nbsp;</span>LigoWave LigoDLB <span>hands-on&nbsp;</span>certificeringskursus&nbsp;</p>\r\n<p><span>&bull;&nbsp;</span><span>LigoWave LigoPTMP&nbsp;<span>hands-on&nbsp;</span></span><span>certificeringskursus&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Netv&aelig;rkskurser&nbsp;</strong></p>\r\n<p>&bull; IP <span>Network&nbsp;specialist</span></p>\r\n<p>&bull; 802.11 Network&nbsp;specialist</p>\r\n<p>&bull; Wireless backbone network&nbsp;specialist</p>\r\n<p>&nbsp;</p>\r\n<p>Tidspunkterne for k<span>urser</span>&nbsp;kan ses p&aring;&nbsp;<a title=\"Kommende events\" href=\"http://www.cloudrouter.dk/events\">Kommende events</a><span>.</span></p>', 0, '', '', '', '', '', 1),
(31, 'profile', 'Profile DK', '<h4>Baggrund</h4>\r\n<p style=\"text-align: justify;\">Vi er passionerede mennesker, med dybe r&oslash;dder i tr&aring;dl&oslash;s datakommunikation. Vi leverer tr&aring;dl&oslash;se internet- og netv&aelig;rksl&oslash;sninger til professionelt brug.&nbsp;Vores drivkraft i Cloud Router er et langvarigt samarbejde mellem vores kunder og samarbejdspartnere, og er baseret p&aring; viden og innovation.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<h4>Viden driver v&aelig;rket</h4>\r\n<p style=\"text-align: justify;\">Cloud Routers kompetence er en sammens&aelig;tning af specialister, der har 20 &aring;rs erfaring indenfor tr&aring;dl&oslash;s kommunikation, samt velkendte producenter af tr&aring;dl&oslash;se l&oslash;sninger. Det betyder at vi arbejder t&aelig;t sammen med vores producenter og teknologi-partnere, og deltager i udviklingen af nye produkter. Det g&oslash;r at vi kan levere skr&aelig;ddersyede l&oslash;sninger til vores kunder. Udformningen af vores l&oslash;sninger styres derfor af kundernes behov og de teknologiske muligheder, der hele tiden udvikles p&aring; omr&aring;det.</p>\r\n<p><span style=\"font-size: 1em;\">&nbsp;</span></p>\r\n<h4><span>Vision</span></h4>\r\n<p style=\"text-align: justify;\">Som vidensbaseret datakommunikationsvirksomhed ser vi det som vores ansvar, at v&aelig;re med til at udvikle og fremtidssikre vores samfund. Det g&oslash;r vi ved at samarbejde med kunden om at lave en individuel, omkostningseffektiv og innovativ l&oslash;sning, med den bedste teknologiske viden p&aring; omr&aring;det.<br /><br />Cloud Routers intention er at skabe kontinuerlig v&aelig;rdi for alle nuv&aelig;rende og kommende kunder, p&aring; hele det nordiske marked.<br /><br />Se mere p&aring; Cloud Routers&nbsp;<a title=\"Bes&oslash;g Cloud Routers blog for projekter, forslag og vejledninger\" href=\"https://blog.cloudrouter.dk/\" target=\"_blank\">Blog</a>, <a title=\"Bes&oslash;g Cloud Routers Linkedin profil\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a> og <a title=\"Bes&oslash;g Cloud Routers Twitter profil\" href=\"https://twitter.com/Cloudrouter_dk\" target=\"_blank\">Twitter</a> profiler.</p>', 0, 'Cloud Router Value-added IT distributør', 'Cloud Router er en Value-added distributør af moderne netværksløsninger', 'WiFi, WLAN, distributør, netværksløsninger, Dansk IT leverandør', '', 'profile', 1),
(28, 'uddannelse', 'uddannelse', NULL, 0, 'Åbent hus arrangementer inden for trådløs datakommunikation', 'Cloud Router tilbyder webinar, kurser og workshops inden for IP og trådløs datakommunikation.', 'Webinar, kurser, workshops, træning, certificering', '', '', 1),
(27, 'forretningsomraader', 'forretningsomraader', NULL, 0, 'Cloud Router - WLAN, Radio-link, Ethernet og Firewall', 'Gennem samarbejde med vores forhandlere, skaber Cloud Router nye rammer for kommunikationsløsninger og services i Danmark ved salg af netværksløsninger.', '', '', '', 1),
(33, 'contact', 'Contact DK', '<table style=\"width: 900px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\"><colgroup><col span=\"5\" width=\"276\" /> </colgroup>\r\n<tbody>\r\n<tr>\r\n<td class=\"xl64\" width=\"276\" height=\"22\"><span style=\"font-size: small;\"><strong>Kontorassistent</strong></span></td>\r\n<td class=\"xl64\" width=\"276\"><span style=\"font-size: small;\"><strong>Bogholder</strong></span></td>\r\n<td class=\"xl64\" width=\"276\"><span style=\"font-size: small;\"><strong><strong>Salg og levering</strong></strong></span></td>\r\n<td class=\"xl64\" width=\"276\"><span style=\"font-size: small;\"><strong>L&oslash;sninger</strong></span></td>\r\n<td class=\"xl64\" width=\"276\"><span style=\"font-size: small;\"><strong><strong>Service</strong></strong></span></td>\r\n</tr>\r\n<tr>\r\n<td class=\"xl65\" height=\"22\"><span style=\"font-size: small; color: #333333;\">Christine F. Knudsen</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\">Karina B&oslash;hm</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\"><span>Peter Koch</span></span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\">Shankar Jeyakumaran</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\"><span>Henry Madsen</span></span></td>\r\n</tr>\r\n<tr>\r\n<td class=\"xl65\" height=\"22\"><span style=\"font-size: small; color: #333333;\">salg[@]cloudrouter.dk</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\">karina[@]cloudrouter.dk</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\"><span>peter[@]cloudrouter.dk</span></span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\">shankar[@]cloudrouter.dk</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small; color: #333333;\"><span>service[@]cloudrouter.dk</span></span></td>\r\n</tr>\r\n<tr>\r\n<td height=\"22\"><span style=\"color: #333333; font-size: small;\">+45 73 11 56 00</span></td>\r\n<td><span style=\"color: #333333; font-size: small;\">+45 73 11 56 00</span></td>\r\n<td><span style=\"color: #333333; font-size: small;\"><span>+45 73115600</span></span></td>\r\n<td><span style=\"color: #333333; font-size: small;\">+45&nbsp;<span>73115600</span></span></td>\r\n<td><span style=\"color: #999999;\"><span style=\"color: #333333; font-size: small;\"><span>+45 73115600</span></span></span></td>\r\n</tr>\r\n<tr>\r\n<td class=\"xl65\" height=\"22\">&nbsp;</td>\r\n<td class=\"xl65\">&nbsp;</td>\r\n<td class=\"xl65\">&nbsp;</td>\r\n<td class=\"xl65\">&nbsp;</td>\r\n<td class=\"xl65\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<table style=\"width: 500px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td class=\"xl64\" width=\"276\"><strong><span style=\"font-size: small;\">Cloud Router ApS</span></strong></td>\r\n<td class=\"xl64\" width=\"276\"><strong><span style=\"font-size: small;\">&Aring;bningstider</span></strong></td>\r\n<td class=\"xl64\" width=\"276\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">Sivmosev&aelig;nget 2L&nbsp;</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">Mandag - torsdag:</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">08:00 - 16:00</span></td>\r\n</tr>\r\n<tr>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">DK-5260 Odense S&nbsp;</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">Fredag:</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">08:00 - 14:00</span></td>\r\n</tr>\r\n<tr>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">CVR:&nbsp;36722339</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">Weekend og helligdage:</span></td>\r\n<td class=\"xl65\"><span style=\"font-size: small;\">Lukket</span></td>\r\n</tr>\r\n</tbody>\r\n</table>', 0, 'Cloud Router kontaktinformation', 'Kontakt Cloud Router', 'cloudrouter kontakt', '', 'profile', 1),
