(566, 'produkter', 'Products FI', '<h3><span style=\"color: #339966;\">Professionel r&aring;dgivning og sparring</span></h3>\r\n<p><span style=\"color: #333333;\">Vi leverer professionel r&aring;dgivning og sparring til&nbsp;virksomheder, offentlige organisationer og uddannelsesektor i forbindelse med&nbsp;WLAN, Ethernet og 4G l&oslash;sninger.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><strong>⨠</strong> Opret&nbsp;en salgssag via </span><a title=\"Cloud Router Online formular\" href=\"http://www.cloudrouter.dk/service\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">O</span>nline formular</span></a></p>\r\n<p><span style=\"color: #000000;\"><strong>⨠ </strong>Kontakte os p&aring; telefonen +45 73 11 56 00</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\">Er du en forhandler, installat&oslash;r&nbsp;eller udbyder, beder vi dig om at&nbsp;l&aelig;se vores partnerfordele p&aring;&nbsp;siden <span style=\"color: #0000ff;\"><a title=\"Cloud Router forhandlerprogram\" href=\"forhandler\"><span style=\"color: #0000ff;\">forhandler</span></a>.</span></span></p>', 0, '', '', '', '', '', 5),
