(568, 'forside_2', 'forside_2', '<h1>Vahvuus</h1>\r\n<p>Cloud Routerilla on suuri kokemus WLAN- ja IP-viestinn&auml;st&auml;. Tiiviiss&auml; yhteisty&ouml;ss&auml; arvostettujen IT-valmistajien kanssa me pystymme ennakoimaan tulevat teknologiset muutokset.</p>\r\n<p>Cloud Router on tunnettu siit&auml;, ett&auml; se jatkuvasti ylitt&auml;&auml; odotukset, joita j&auml;lleenmyyj&auml;t asettavat jakelijoille. Hands-on ja huomion keskitt&auml;minen uusien ja parempien ratkaisujen l&ouml;yt&auml;miseksi.</p>\r\n<p>&nbsp;</p>', 0, '', '', '', '', '', 5),
(565, NULL, 'service', '<p><div class=\"meddelelse_boks center_container\"><span style=\"color:red;\">Siden blev desværre ikke fundet. Du bliver viderestillet til forsiden.</span></div>\r\n</p>\r\n<script type=\"text/javascript\">setTimeout(\"location.href=\'index.php\';\",2000);</script>', 0, '', '', '', '', '', 5),
