(560, 'contact', 'Contact SE', '<h3>Company information</h3>\r\n<p>Cloud Router ApS</p>\r\n<p>Virkelyst 20, DK-7400 Herning</p>\r\n<p>Svendborgvej 226, DK-5260 Odense S</p>\r\n<p>Denmark</p>\r\n<p>&nbsp;</p>\r\n<p>Telefon: +45 73 11 56 00 - Email: <a href=\"mailto:kontor@cloudrouter.dk\">kontor@cloudrouter.dk</a></p>\r\n<p>Monday - Thursday 08:30 to 16:00 and Friday 08:30 to 15:00 CET</p>', 0, 'Cloud Router kontaktinformation', 'Kontakt Cloud Router', 'cloudrouter kontakt', '', 'profile', 3),
(561, 'forside', 'Forside', '<p><em>Cloud Router&nbsp;etablerer et v&aelig;rdiskabende samarbejde der skaber b&aelig;redygtige relationer.</em></p>', 0, 'Professionelle WiFi, Point-to-point og LTE trådløse løsninger', 'Vidensbaseret distributør med spidskompetence inden for WiFi, WLAN og LTE datakommunikation', 'Distributør, leverandør, WiFi, WLAN, punkt til punkt, Ethernet, WAN, M2M, IoT, Radiolink, radio link, trådløs bro, WLAN bridge, WiFi bro, WiFi bridge, trådløst netværk, skole netværk, industri netværk, routing, switching, switch, router, firewall', '', '', 5),
