(529, 'contact', 'Contact GL', '<table border=\"0\" align=\"left\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<h4><strong>Jylland adresse</strong></h4>\r\n</td>\r\n<td>\r\n<h4><strong>Fyn adresse</strong></h4>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>Cloud Router ApS</td>\r\n<td>Cloud Router ApS</td>\r\n</tr>\r\n<tr>\r\n<td>Virkelyst 20</td>\r\n<td>Svendborgvej 226</td>\r\n</tr>\r\n<tr>\r\n<td>DK-7400 Herning</td>\r\n<td>DK-5260 Odense S</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ansvarsomr&aring;der&nbsp;og &aring;bningstider</strong></td>\r\n<td><strong>Ansvarsomr&aring;der&nbsp;og &aring;bningstider</strong></td>\r\n</tr>\r\n<tr>\r\n<td>Teknisk service, lager og bogholderi</td>\r\n<td>Salgssparring og partneraftaler</td>\r\n</tr>\r\n<tr>\r\n<td>Man - tor 08:30 - 16:00 og fredag til 15:00</td>\r\n<td>Man - tor 08:30 - 16:00 og fredag til 14:00</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Kontaktinformationer</strong></td>\r\n<td><strong>Kontaktinformationer</strong></td>\r\n</tr>\r\n<tr>\r\n<td>E-mail: kontor[@]cloudrouter.dk</td>\r\n<td>E-mail: solution[@]cloudrouter.dk</td>\r\n</tr>\r\n<tr>\r\n<td>Telefon: +45 73 11 56 00</td>\r\n<td>Telefon: +45 73 11 56 00</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Kontaktinformationer og retningslinjerne for teknisk assistance, kan findes&nbsp;p&aring;&nbsp;<span>siden</span> <span><span><a title=\"Cloud Router\'s service vejledning\" href=\"http://www.cloudrouter.dk/service\">Service</a><span>.</span></span></span></p>\r\n<p><span><span><span>Bes&oslash;g vores&nbsp;<a title=\"Cloud Router Youtube channel\" href=\"https://www.youtube.com/channel/UCDgG8PF_fGdhVLwSXiOJ87g\" target=\"_blank\">YouTube</a>, <a title=\"Cloud Router\'s Online blog\" href=\"https://blog.cloudrouter.dk\" target=\"_blank\">Onine-blog</a>&nbsp;og <a title=\"Cloud Router Linkedin\" href=\"https://www.linkedin.com/company/cloud-router\" target=\"_blank\">Linkedin</a>&nbsp;profiler eller kontakt os for yderligere information.</span></span></span></p>', 0, 'Cloud Router kontaktinformation', 'Kontakt Cloud Router', 'cloudrouter kontakt', '', 'profile', 2),
(530, 'forside', 'Forside', '<p><em>Cloud Router&nbsp;etablerer et v&aelig;rdiskabende samarbejde der skaber b&aelig;redygtige relationer.</em></p>', 0, 'Professionelle WiFi, Point-to-point og LTE trådløse løsninger', 'Vidensbaseret distributør med spidskompetence inden for WiFi, WLAN og LTE datakommunikation', 'Distributør, leverandør, WiFi, WLAN, punkt til punkt, Ethernet, WAN, M2M, IoT, Radiolink, radio link, trådløs bro, WLAN bridge, WiFi bro, WiFi bridge, trådløst netværk, skole netværk, industri netværk, routing, switching, switch, router, firewall', '', '', 3),
